import { readFile, writeFile } from 'node:fs/promises';
const files = [
  'install.sh',
  'synology-check.sh',
  'synocommunity.sh',
  'installer/json-paths.awk',
  'installer/login-entry.sh',
  'login-nginx.conf',
];
let script =
  '#!/bin/sh\n# Generated by scripts/build-installer.mjs. Edit release/installer/main.sh and helpers.\n';
script += 'extract_helpers() {\n';
for (const [index, file] of files.entries()) {
  const source = await readFile(`release/${file}`, 'utf8');
  const delimiter = `TWUI_EMBEDDED_HELPER_${index}_END`;
  if (source.includes(delimiter)) throw new Error('Embedded delimiter collision');
  script += `cat > "$work/${file.split('/').at(-1)}" <<'${delimiter}'\n${source}\n${delimiter}\n`;
}
script += '}\n';
script += await readFile('release/installer/main.sh', 'utf8');
await writeFile('release/install-transmission-web-ui.sh', script, { mode: 0o755 });
console.log('Single-file installer generated: release/install-transmission-web-ui.sh');
